import { scheduleLessons, type LessonSource } from './curriculum/model';
export const months=['JavaScript Fundamentals','Advanced JavaScript','TypeScript','React','Next.js','Backend Engineering','MongoDB & Databases','Computer Science','Algorithms','Software Engineering','DevOps & Cloud','Final SaaS Project'];
const originalLessons: LessonSource[] = [
{id:'js-001',month:1,title:'Variables: const & let',minutes:25,body:'Variables store values. Use const when a value should not be reassigned, and let when it will change.',code:"const name = 'Developer';\nlet score = 0;\nscore += 10;",question:'Which keyword allows reassignment?',choices:['const','let','import'],correct:1},
{id:'js-002',month:1,title:'JavaScript Data Types',minutes:25,body:'Strings contain text, numbers represent numeric values, and booleans are true or false.',code:"const age = 15;\nconst ready = true;\nconst language = 'JavaScript';",question:'What type is true?',choices:['string','number','boolean'],correct:2},
{id:'js-003',month:1,title:'Functions',minutes:25,body:'Functions group reusable logic. Parameters are inputs and return gives back a result.',code:"function add(a, b) {\n  return a + b;\n}\nadd(2, 3);",question:'Which keyword returns a result?',choices:['return','let','break'],correct:0}
,{id:'js-004',month:1,title:'Arrays and Indexes',minutes:25,body:'Arrays hold ordered collections. The first element has index 0. Use length to count elements.',code:"const skills = ['HTML', 'CSS', 'JS'];\nconsole.log(skills[0]);\nconsole.log(skills.length);",question:'What is the first array index?',choices:['1','0','-1'],correct:1},
{id:'js-005',month:1,title:'Objects and Properties',minutes:25,body:'Objects store related information as named properties. Read a property using dot notation.',code:"const user = { name: 'Ali', level: 1 };\nconsole.log(user.name);",question:'Which reads the name property?',choices:['user.name','user->name','user[name]'],correct:0},
{id:'js-006',month:1,title:'Conditions: if and else',minutes:25,body:'Conditional statements let programs make decisions based on true or false expressions.',code:"const score = 80;\nif (score >= 60) {\n  console.log('Pass');\n} else {\n  console.log('Retry');\n}",question:'Which keyword handles the alternative branch?',choices:['const','else','return'],correct:1},
{id:'js-007',month:1,title:'Loops',minutes:25,body:'Loops repeat actions. A for loop can count through a fixed number of iterations.',code:"for (let i = 0; i < 3; i++) {\n  console.log(i);\n}",question:'How many values are logged?',choices:['2','3','4'],correct:1},
{id:"js-008",month:1,title:"Comparison Operators",minutes:25,body:"Use === and !== to compare values without type coercion. Comparison expressions produce booleans. Prefer strict equality to ==.",code:"const age = 15;\nconsole.log(age === 15); // true\nconsole.log(age !== '15'); // true",question:"What does 5 === '5' evaluate to?",choices:["true","false","undefined"],correct:1},
{id:"js-009",month:1,title:"Logical Operators",minutes:25,body:"&& requires both conditions to be truthy, || needs at least one truthy condition, and ! reverses a boolean.",code:"const hasAccount = true;\nconst verified = false;\nconsole.log(hasAccount && verified); // false\nconsole.log(hasAccount || verified); // true",question:"What is true && false?",choices:["true","false","null"],correct:1},
{id:"js-010",month:1,title:"Array Methods: map and filter",minutes:25,body:"map creates a new array by transforming each item. filter creates a new array containing only items that pass a condition. Neither changes the original array.",code:"const scores = [30, 70, 90];\nconst doubled = scores.map(x => x * 2);\nconst passed = scores.filter(x => x >= 60);",question:"Which method keeps only matching elements?",choices:["map","filter","push"],correct:1},
{id:"js-011",month:1,title:"Template Literals",minutes:25,body:"Template literals use backticks and ${...} to insert values into strings. They also support multiline text.",code:"const name = 'Sam';\nconst points = 42;\nconst message = `Hi ${name}, you have ${points} points`;",question:"Which characters enclose a template literal?",choices:["Backticks (`)","Single quotes (')","Parentheses ()"],correct:0},
{id:"js-012",month:1,title:"Destructuring",minutes:25,body:"Destructuring extracts values from arrays or properties from objects into local variables. Object destructuring uses property names.",code:"const student = { name: 'Amina', score: 90 };\nconst { name, score } = student;\nconst [first, second] = ['JS', 'TS'];",question:"What does const { name } = student extract?",choices:["The name property","The entire object","The first array item"],correct:0},
{id:"js-013",month:1,title:"Spread and Rest Syntax",minutes:25,body:"Spread expands array or object values into a new collection. Rest gathers remaining values into a single variable. Both use ... in different positions.",code:"const base = [1, 2];\nconst more = [...base, 3];\nfunction sum(...nums) {\n  return nums.reduce((a, b) => a + b, 0);\n}",question:"What is [...[1, 2], 3]?",choices:["[1, 2, 3]","[[1, 2], 3]","[3, 1, 2]"],correct:0},
{id:"js-014",month:1,title:"Scope and Block Variables",minutes:25,body:"Variables declared with let and const inside a block are only accessible within that block. This helps avoid accidental reuse.",code:"if (true) {\n  const message = 'inside';\n  console.log(message);\n}\n// message is not defined here",question:"Where can a const declared inside an if block be accessed?",choices:["Anywhere","Inside that block","Only in another function"],correct:1},
{"id":"js-015","month":1,"title":"Truthy and Falsy Values","minutes":25,"body":"JavaScript conditions convert values to booleans. false, 0, empty strings, null, undefined and NaN are falsy; empty arrays and objects are truthy.","code":"console.log(Boolean('')); // false\nconsole.log(Boolean([])); // true\nconsole.log(Boolean(0)); // false","question":"Which value is truthy?","choices":["0","''","[]"],"correct":2},
{"id":"js-016","month":1,"title":"Nullish Coalescing and Optional Chaining","minutes":25,"body":"Optional chaining ?. safely accesses properties that may be missing. Nullish coalescing ?? uses a fallback only for null or undefined, not for 0 or an empty string.","code":"const user = { settings: { theme: 'dark' } };\nconst theme = user.settings?.theme ?? 'light';\nconst count = 0 ?? 10; // 0","question":"What is the result of 0 ?? 10?","choices":["0","10","undefined"],"correct":0},
{"id":"js-017","month":1,"title":"for...of and for...in","minutes":25,"body":"Use for...of to iterate over values in an iterable such as an array. Use for...in to iterate over enumerable property keys of an object.","code":"for (const value of ['a', 'b']) {\n  console.log(value);\n}\nfor (const key in { x: 1 }) {\n  console.log(key);\n}","question":"Which loop iterates array values directly?","choices":["for...in","for...of","while...key"],"correct":1},
{"id":"js-018","month":1,"title":"Error Handling: try and catch","minutes":25,"body":"Use try/catch to handle exceptions thrown by synchronous code. The finally block runs after try/catch regardless of success or failure.","code":"try {\n  JSON.parse('{bad json}');\n} catch (error) {\n  console.log('Invalid JSON');\n} finally {\n  console.log('Finished');\n}","question":"Which block handles a thrown error?","choices":["try","catch","finally"],"correct":1},
{"id":"js-019","month":1,"title":"JSON and Data Serialization","minutes":25,"body":"JSON.stringify converts supported JavaScript values into JSON text. JSON.parse converts valid JSON text back into JavaScript data. JSON cannot represent functions.","code":"const data = { title: 'Lesson', done: false };\nconst text = JSON.stringify(data);\nconst restored = JSON.parse(text);","question":"Which function converts JSON text to an object?","choices":["JSON.stringify","JSON.parse","JSON.object"],"correct":1},
{"id":"js-020","month":1,"title":"Functions and Arrow Syntax","minutes":25,"body":"Arrow functions offer concise syntax and capture this lexically. A concise expression body returns its expression automatically.","code":"const square = n => n * n;\nconst greet = name => `Hello, ${name}`;\nconsole.log(square(4)); // 16","question":"What does n => n * n return for n = 3?","choices":["6","9","undefined"],"correct":1},
{"id":"js-021","month":1,"title":"Mini Project: Score Tracker","minutes":25,"body":"Combine arrays, objects, functions, and conditions to build a small score tracker. Use reduce to calculate a total and a comparison to determine passing status.","code":"const scores = [60, 80, 100];\nconst total = scores.reduce((sum, n) => sum + n, 0);\nconst average = total / scores.length;\nconst passed = average >= 70;\nconsole.log({ average, passed });","question":"What is the average of [60, 80, 100]?","choices":["70","80","90"],"correct":1},
{"id":"js-022","month":2,"title":"Execution Context and Call Stack","minutes":25,"body":"JavaScript runs functions in execution contexts. The call stack tracks active function calls; the most recent call returns first.","code":"function first() { second(); }\nfunction second() { console.log('done'); }\nfirst();","question":"Which function is called by first()?","choices":["first","second","console"],"correct":1},
{"id":"js-023","month":2,"title":"Hoisting and Temporal Dead Zone","minutes":25,"body":"Function declarations can be called before their definition. let and const bindings exist before initialization but cannot be accessed during the temporal dead zone.","code":"sayHi();\nfunction sayHi() { console.log('Hi'); }\n// console.log(x) before let x = 1 throws","question":"Which declaration can be called before its definition?","choices":["Function declaration","const arrow function","let variable"],"correct":0},
{"id":"js-024","month":2,"title":"Closures","minutes":25,"body":"A closure lets a function access variables from the lexical scope where it was created, even after the outer function returns.","code":"function counter() {\n  let count = 0;\n  return () => ++count;\n}\nconst next = counter();\nconsole.log(next()); // 1","question":"What does the second next() call return?","choices":["1","2","0"],"correct":1},
{"id":"js-025","month":2,"title":"this and Method Calls","minutes":25,"body":"For a regular function called as an object method, this normally refers to the object. Arrow functions do not create their own this binding.","code":"const player = {\n  name: 'Ada',\n  greet() { return this.name; }\n};\nconsole.log(player.greet());","question":"What does player.greet() return?","choices":["Ada","undefined","player"],"correct":0},
{"id":"js-026","month":2,"title":"Prototypes and Inheritance","minutes":25,"body":"JavaScript objects can inherit properties through a prototype chain. Classes provide syntax built on this prototype-based model.","code":"class Animal { speak() { return 'sound'; } }\nclass Dog extends Animal {}\nconst dog = new Dog();\nconsole.log(dog.speak());","question":"How does Dog inherit speak()?","choices":["Through prototype inheritance","Through JSON","Through a loop"],"correct":0},
{"id":"js-027","month":2,"title":"Higher-Order Functions","minutes":25,"body":"A higher-order function accepts a function or returns a function. Array map, filter and reduce are common examples.","code":"function apply(value, fn) { return fn(value); }\nconsole.log(apply(4, n => n * 3));","question":"What is apply(4, n => n * 3)?","choices":["7","12","3"],"correct":1},
{"id":"js-028","month":2,"title":"Reduce and Aggregation","minutes":25,"body":"reduce combines array items into a single accumulated value. Supply an initial accumulator to handle empty arrays safely.","code":"const prices = [5, 10, 15];\nconst total = prices.reduce((sum, n) => sum + n, 0);\nconsole.log(total);","question":"What does the total equal?","choices":["15","30","0"],"correct":1},
{"id":"js-029","month":2,"title":"Promises: States and Chaining","minutes":25,"body":"A Promise represents an eventual result: pending, fulfilled or rejected. then handles fulfillment and catch handles rejection.","code":"Promise.resolve(5)\n  .then(n => n * 2)\n  .then(console.log)\n  .catch(console.error);","question":"What is logged by the fulfilled chain?","choices":["5","10","undefined"],"correct":1},
{"id":"js-030","month":2,"title":"Async and Await","minutes":25,"body":"An async function always returns a Promise. await pauses that async function until the awaited Promise settles; errors can be handled with try/catch.","code":"async function getValue() {\n  const n = await Promise.resolve(7);\n  return n + 1;\n}\ngetValue().then(console.log);","question":"What value is logged?","choices":["7","8","Promise"],"correct":1},
{"id":"js-031","month":2,"title":"Event Loop and Microtasks","minutes":25,"body":"Synchronous code runs first. Promise callbacks are queued as microtasks, which run before timer callbacks in a later task.","code":"console.log('A');\nsetTimeout(() => console.log('C'), 0);\nPromise.resolve().then(() => console.log('B'));","question":"What is the log order?","choices":["A B C","A C B","B A C"],"correct":0},
{"id":"js-032","month":2,"title":"Promise.all and Parallel Tasks","minutes":25,"body":"Promise.all waits for all input Promises to fulfill, preserving input order. If any rejects, the combined Promise rejects.","code":"const values = await Promise.all([\n  Promise.resolve(2),\n  Promise.resolve(4)\n]);\nconsole.log(values);","question":"What does Promise.all return here?","choices":["[2, 4]","6","[4, 2]"],"correct":0},
{"id":"js-033","month":2,"title":"Fetch and HTTP Basics","minutes":25,"body":"fetch returns a Promise for a Response. Check response.ok before parsing. Network requests require connectivity, unlike bundled offline lessons.","code":"async function load(url) {\n  const response = await fetch(url);\n  if (!response.ok) throw new Error('HTTP error');\n  return response.json();\n}","question":"Which property indicates a successful 2xx response?","choices":["response.ok","response.json","response.url"],"correct":0},
{"id":"js-034","month":2,"title":"ES Modules","minutes":25,"body":"ES modules export reusable values and import them in other files. Named exports use braces; default exports are imported without braces.","code":"// math.js\nexport const double = n => n * 2;\n// app.js\nimport { double } from './math.js';","question":"How do you import a named export double?","choices":["import { double }","import * as double from","require default double"],"correct":0},
{"id":"js-035","month":2,"title":"Map and Set","minutes":25,"body":"Map stores key-value pairs and allows keys of any type. Set stores unique values and removes duplicates from a list.","code":"const unique = [...new Set([1, 1, 2])];\nconst map = new Map([['a', 10]]);\nconsole.log(unique, map.get('a'));","question":"How many items are in new Set([1,1,2])?","choices":["3","2","1"],"correct":1},
{"id":"js-036","month":2,"title":"Debouncing and Timers","minutes":25,"body":"Debouncing delays an action until a quiet period has passed. Clearing the previous timer prevents repeated execution during rapid input.","code":"let timer;\nfunction debounceAction() {\n  clearTimeout(timer);\n  timer = setTimeout(() => console.log('run'), 300);\n}","question":"Why call clearTimeout(timer)?","choices":["Cancel previous scheduled run","Run immediately","Stop all JavaScript"],"correct":0},
{"id":"js-037","month":2,"title":"Advanced Mini Project: Task Queue","minutes":25,"body":"Combine Promises, async/await and error handling to process tasks in sequence. This exercise illustrates ordered asynchronous operations.","code":"async function runTasks(tasks) {\n  const results = [];\n  for (const task of tasks) {\n    results.push(await task());\n  }\n  return results;\n}\nrunTasks([() => Promise.resolve(1), () => Promise.resolve(2)]).then(console.log);","question":"What is the result of the example task queue?","choices":["[1, 2]","[2, 1]","1"],"correct":0},
{"id":"ts-001","month":3,"title":"Why TypeScript?","minutes":25,"body":"TypeScript adds static type checking to JavaScript. Types are checked during development and erased when code is compiled to JavaScript.","code":"let username: string = 'Ada';\nlet score: number = 10;\nlet active: boolean = true;","question":"Which type represents true or false?","choices":["string","boolean","number"],"correct":1},
{"id":"ts-002","month":3,"title":"Type Inference","minutes":25,"body":"TypeScript often infers variable types from initial values, so explicit annotations are not always needed.","code":"const language = 'TypeScript';\nlet points = 5;\npoints += 2;","question":"What type is inferred for points?","choices":["string","number","boolean"],"correct":1},
{"id":"ts-003","month":3,"title":"Arrays and Tuples","minutes":25,"body":"TypeScript arrays describe element types. Tuples describe a fixed number of elements with types at known positions.","code":"const skills: string[] = ['JS', 'TS'];\nconst result: [string, number] = ['Ada', 95];","question":"What is the type of skills?","choices":["string[]","number[]","boolean[]"],"correct":0},
{"id":"ts-004","month":3,"title":"Object Types","minutes":25,"body":"Describe the properties an object must contain using a type alias. Type checking catches missing or mismatched properties.","code":"type Student = { name: string; age: number };\nconst student: Student = { name: 'Ada', age: 16 };","question":"Which property must be a number?","choices":["name","age","student"],"correct":1},
{"id":"ts-005","month":3,"title":"Optional Properties","minutes":25,"body":"A question mark after a property name makes it optional. Check for undefined before using optional values.","code":"type Profile = { name: string; bio?: string };\nconst profile: Profile = { name: 'Sam' };","question":"What does bio? mean?","choices":["Required property","Optional property","Readonly property"],"correct":1},
{"id":"ts-006","month":3,"title":"Union Types","minutes":25,"body":"A union type allows a value to be one of several types. Narrow the type before calling type-specific methods.","code":"let id: string | number = 42;\nid = 'user-42';","question":"What can id contain?","choices":["Only numbers","Strings or numbers","Only booleans"],"correct":1},
{"id":"ts-007","month":3,"title":"Literal Types","minutes":25,"body":"Literal types restrict a value to specific strings or numbers, which is useful for status and configuration values.","code":"type Status = 'idle' | 'loading' | 'done';\nconst status: Status = 'loading';","question":"Which value is valid for Status?","choices":["'error'","'loading'","'ready'"],"correct":1},
{"id":"ts-008","month":3,"title":"Function Parameters and Returns","minutes":25,"body":"Annotate function parameters and optionally the return type. TypeScript checks that the implementation matches.","code":"function multiply(a: number, b: number): number {\n  return a * b;\n}\nconst result = multiply(3, 4);","question":"What is multiply(3, 4)?","choices":["7","12","34"],"correct":1},
{"id":"ts-009","month":3,"title":"Interfaces","minutes":25,"body":"An interface describes the shape of an object and can be extended. Interfaces and type aliases overlap for many object shapes.","code":"interface User { name: string }\ninterface Admin extends User { role: 'admin' }\nconst admin: Admin = { name: 'Ada', role: 'admin' };","question":"Which keyword extends an interface?","choices":["extends","implementsOnly","import"],"correct":0},
{"id":"ts-010","month":3,"title":"Type Narrowing","minutes":25,"body":"typeof and other checks help TypeScript narrow union types inside branches.","code":"function format(value: string | number) {\n  if (typeof value === 'string') return value.toUpperCase();\n  return value.toFixed(2);\n}","question":"Which check narrows value to string?","choices":["typeof value === 'string'","value === null","Array.isArray(value)"],"correct":0},
{"id":"ts-011","month":3,"title":"Generics","minutes":25,"body":"Generics preserve relationships between input and output types without using any.","code":"function identity<T>(value: T): T { return value; }\nconst count = identity(10);\nconst label = identity('Hi');","question":"What is inferred for identity(10)?","choices":["string","number","boolean"],"correct":1},
{"id":"ts-012","month":3,"title":"Readonly and Utility Types","minutes":25,"body":"Readonly prevents reassignment of object properties during type checking. Partial makes properties optional.","code":"type Settings = { theme: string; fontSize: number };\ntype Draft = Partial<Settings>;\nconst draft: Draft = { theme: 'dark' };","question":"What does Partial<Settings> do?","choices":["Makes fields optional","Deletes all fields","Converts fields to numbers"],"correct":0},
{"id":"ts-013","month":3,"title":"Async Function Types","minutes":25,"body":"An async function returns Promise<T>. Annotate the resolved type for clarity.","code":"async function getCount(): Promise<number> {\n  return 5;\n}\ngetCount().then(console.log);","question":"What is the return type of getCount()?","choices":["number","Promise<number>","string"],"correct":1},
{"id":"ts-014","month":3,"title":"Discriminated Unions","minutes":25,"body":"A shared literal property helps TypeScript narrow related object variants safely.","code":"type Result = { ok: true; value: number } | { ok: false; error: string };\nfunction read(result: Result) {\n  return result.ok ? result.value : result.error;\n}","question":"Which property distinguishes the variants?","choices":["value","ok","error"],"correct":1},
{"id":"ts-015","month":3,"title":"Unknown vs Any","minutes":25,"body":"unknown requires narrowing before use; any bypasses type checking. Prefer unknown for untrusted data.","code":"function show(value: unknown) {\n  if (typeof value === 'string') console.log(value.toUpperCase());\n}","question":"Which type requires a check before string methods?","choices":["any","unknown","never"],"correct":1},
{"id":"ts-016","month":3,"title":"Mini Project: Typed Task List","minutes":25,"body":"Combine interfaces, unions, arrays and functions into a typed task manager. The example adds a task and filters completed ones.","code":"type Task = { id: number; title: string; done: boolean };\nconst tasks: Task[] = [{ id: 1, title: 'Learn TS', done: true }];\nconst completed = tasks.filter(task => task.done);\nconsole.log(completed.length);","question":"How many completed tasks are in the example?","choices":["0","1","2"],"correct":1},
{"id":"react-001","month":4,"title":"React Components","minutes":25,"body":"React builds interfaces from reusable components. A component is a function that returns JSX describing UI.","code":"function Welcome() {\n  return <h1>Hello React</h1>;\n}","question":"What does a React component return?","choices":["JSX","A database","A server"],"correct":0},
{"id":"react-002","month":4,"title":"JSX Expressions","minutes":25,"body":"JSX lets you embed JavaScript expressions in braces. Use className for CSS classes on the web.","code":"const name = 'Ada';\nconst heading = <h1>Hello, {name}</h1>;","question":"How do you insert a JS expression in JSX?","choices":["With braces {}","With SQL","With backticks only"],"correct":0},
{"id":"react-003","month":4,"title":"Props and Reuse","minutes":25,"body":"Props pass data from a parent to a child component. Treat props as read-only inputs.","code":"function Badge({ label }: { label: string }) {\n  return <span>{label}</span>;\n}\nconst view = <Badge label='Student' />;","question":"Where does Badge receive label?","choices":["Props","Local storage","A timer"],"correct":0},
{"id":"react-004","month":4,"title":"State with useState","minutes":25,"body":"useState stores component-local state and schedules a re-render when updated. Do not mutate state directly.","code":"function Counter() {\n  const [count, setCount] = React.useState(0);\n  return <button onClick={() => setCount(c => c + 1)}>{count}</button>;\n}","question":"Which function updates count?","choices":["setCount","useEffect","console.log"],"correct":0},
{"id":"react-005","month":4,"title":"Event Handling","minutes":25,"body":"React event handlers are functions passed to props such as onClick. Pass a function rather than calling it during rendering.","code":"function SaveButton() {\n  const save = () => console.log('Saved');\n  return <button onClick={save}>Save</button>;\n}","question":"Which prop handles a click on a web button?","choices":["onClick","href","value"],"correct":0},
{"id":"react-006","month":4,"title":"Conditional Rendering","minutes":25,"body":"Render different UI based on conditions using if, ternary expressions or &&. Keep conditional branches readable.","code":"function Status({ online }: { online: boolean }) {\n  return <p>{online ? 'Online' : 'Offline'}</p>;\n}","question":"What displays when online is false?","choices":["Online","Offline","Nothing"],"correct":1},
{"id":"react-007","month":4,"title":"Rendering Lists and Keys","minutes":25,"body":"Use map to render arrays. Give each stable item a unique key so React can reconcile updates correctly.","code":"const tasks = [{ id: 1, title: 'Read' }];\nconst list = <ul>{tasks.map(t => <li key={t.id}>{t.title}</li>)}</ul>;","question":"Which value is a stable key here?","choices":["t.id","Math.random()","Array length"],"correct":0},
{"id":"react-008","month":4,"title":"Controlled Forms","minutes":25,"body":"Controlled inputs receive a value from React state and update it through an event handler.","code":"function NameField() {\n  const [name, setName] = React.useState('');\n  return <input value={name} onChange={e => setName(e.target.value)} />;\n}","question":"Which prop supplies the current input text?","choices":["value","placeholder","type"],"correct":0},
{"id":"react-009","month":4,"title":"useEffect and Cleanup","minutes":25,"body":"useEffect synchronizes a component with external systems. Return a cleanup function to remove subscriptions or timers.","code":"React.useEffect(() => {\n  const timer = setInterval(() => console.log('tick'), 1000);\n  return () => clearInterval(timer);\n}, []);","question":"What removes the interval?","choices":["clearInterval","setInterval","useState"],"correct":0},
{"id":"react-010","month":4,"title":"Custom Hooks","minutes":25,"body":"A custom hook extracts reusable stateful logic. Its name begins with use and it must follow the Rules of Hooks.","code":"function useToggle(initial = false) {\n  const [on, setOn] = React.useState(initial);\n  return { on, toggle: () => setOn(v => !v) };\n}","question":"What should a custom hook name begin with?","choices":["use","get","make"],"correct":0},
{"id":"react-011","month":4,"title":"Lifting State Up","minutes":25,"body":"When sibling components need shared state, move the state to their closest common parent and pass values and callbacks as props.","code":"function Parent() {\n  const [query, setQuery] = React.useState('');\n  return <><input value={query} onChange={e => setQuery(e.target.value)} /><p>{query}</p></>;\n}","question":"Where should shared sibling state live?","choices":["Closest common parent","In both siblings separately","Inside CSS"],"correct":0},
{"id":"react-012","month":4,"title":"Context API","minutes":25,"body":"Context passes values through a component tree without manually forwarding props at every level. Use it for shared cross-cutting data.","code":"const ThemeContext = React.createContext('light');\nfunction App() {\n  return <ThemeContext.Provider value='dark'><Panel /></ThemeContext.Provider>;\n}","question":"Which hook reads a context value?","choices":["useContext","useState","useRef"],"correct":0},
{"id":"react-013","month":4,"title":"useRef","minutes":25,"body":"useRef stores a mutable value across renders without triggering a re-render when current changes. It can also reference DOM nodes.","code":"function Search() {\n  const inputRef = React.useRef<HTMLInputElement>(null);\n  return <input ref={inputRef} />;\n}","question":"Does changing ref.current itself trigger a re-render?","choices":["Yes","No","Always twice"],"correct":1},
{"id":"react-014","month":4,"title":"useMemo and useCallback","minutes":25,"body":"useMemo caches a calculated value; useCallback caches a function identity. Use them when measurement or dependencies justify it.","code":"const filtered = React.useMemo(() => items.filter(x => x.done), [items]);\nconst handleSave = React.useCallback(() => save(id), [id]);","question":"Which hook caches a calculated value?","choices":["useMemo","useEffect","useRef"],"correct":0},
{"id":"react-015","month":4,"title":"React Router Concepts","minutes":25,"body":"In web React apps, routers map URL paths to screens. React Router is common on web; Expo Router handles navigation in this mobile academy.","code":"// React Router (web example)\n<Routes>\n  <Route path='/' element={<Home />} />\n  <Route path='/about' element={<About />} />\n</Routes>","question":"Which router is used by this Expo mobile academy?","choices":["Expo Router","React Router DOM","Express Router"],"correct":0},
{"id":"react-016","month":4,"title":"Mini Project: React Todo List","minutes":25,"body":"Combine state, forms and list rendering. This mini project adds new tasks and renders the list. For production apps, give tasks stable IDs rather than using array indexes as keys.","code":"function Todo() {\n  const [tasks, setTasks] = React.useState<string[]>([]);\n  const [text, setText] = React.useState('');\n  return <><input value={text} onChange={e => setText(e.target.value)} />\n    <button onClick={() => { if (text.trim()) { setTasks(v => [...v, text]); setText(''); } }}>Add</button>\n    <ul>{tasks.map((t, i) => <li key={i}>{t}</li>)}</ul></>;\n}","question":"Which hook stores the tasks array?","choices":["useState","useContext","useEffect"],"correct":0},
{"id":"next-001","month":5,"title":"Next.js and App Router","minutes":25,"body":"Next.js is a React framework. The App Router uses the app directory and file conventions to define routes, layouts and server-rendered UI.","code":"// app/page.tsx\nexport default function Home() {\n  return <h1>Welcome to Next.js</h1>;\n}","question":"Which directory defines App Router routes?","choices":["app","public","node_modules"],"correct":0},
{"id":"next-002","month":5,"title":"Pages and Nested Routes","minutes":25,"body":"A page.tsx file makes a route publicly accessible. Nested folders form URL segments in the App Router.","code":"// app/about/page.tsx\nexport default function About() {\n  return <h1>About us</h1>;\n}","question":"What URL path does app/about/page.tsx define?","choices":["/about","/page","/app"],"correct":0},
{"id":"next-003","month":5,"title":"Layouts","minutes":25,"body":"A layout.tsx file wraps child routes and preserves shared UI across navigation. The root layout must render html and body elements.","code":"// app/layout.tsx\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return <html lang='en'><body>{children}</body></html>;\n}","question":"Which prop renders nested route content?","choices":["children","params","query"],"correct":0},
{"id":"next-004","month":5,"title":"Server and Client Components","minutes":25,"body":"App Router components are Server Components by default. Add 'use client' to a module when it needs browser event handlers or client hooks.","code":"'use client';\nimport { useState } from 'react';\nexport default function Counter() {\n  const [count, setCount] = useState(0);\n  return <button onClick={() => setCount(n => n + 1)}>{count}</button>;\n}","question":"Which directive marks a Client Component?","choices":["'use client'","'use server'","'use browser'"],"correct":0},
{"id":"next-005","month":5,"title":"Navigation with Link","minutes":25,"body":"next/link provides client-side navigation between routes and can prefetch links. Use it for internal navigation.","code":"import Link from 'next/link';\nexport default function Nav() {\n  return <Link href='/about'>About</Link>;\n}","question":"Which component is recommended for internal links?","choices":["Link","img","script"],"correct":0},
{"id":"next-006","month":5,"title":"Dynamic Route Segments","minutes":25,"body":"Square-bracket folder names create dynamic route segments, such as app/blog/[slug]/page.tsx. In current Next.js versions, route params are asynchronous.","code":"// app/blog/[slug]/page.tsx\nexport default async function Post({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  return <h1>{slug}</h1>;\n}","question":"What does [slug] represent?","choices":["Dynamic URL segment","CSS class","Environment variable"],"correct":0},
{"id":"next-007","month":5,"title":"Loading and Error Boundaries","minutes":25,"body":"loading.tsx displays a loading UI for a route segment. error.tsx is a Client Component that catches rendering errors in its segment.","code":"// app/dashboard/loading.tsx\nexport default function Loading() {\n  return <p>Loading dashboard…</p>;\n}","question":"Which file provides route loading UI?","choices":["loading.tsx","page.json","middleware.css"],"correct":0},
{"id":"next-008","month":5,"title":"Data Fetching on the Server","minutes":25,"body":"Server Components can fetch data with async/await. Handle errors and consider caching and revalidation based on the application's needs.","code":"export default async function Page() {\n  const res = await fetch('https://example.com/api/posts');\n  if (!res.ok) throw new Error('Request failed');\n  const posts: { id: number }[] = await res.json();\n  return <p>{posts.length} posts</p>;\n}","question":"Where can an async Server Component fetch data?","choices":["On the server","Only in a browser event","Only in CSS"],"correct":0},
{"id":"next-009","month":5,"title":"Route Handlers","minutes":25,"body":"Route Handlers are defined in route.ts files and export HTTP method functions such as GET or POST. They run on the server.","code":"// app/api/health/route.ts\nexport async function GET() {\n  return Response.json({ ok: true });\n}","question":"Which file defines an App Router Route Handler?","choices":["route.ts","layout.css","page.md"],"correct":0},
{"id":"next-010","month":5,"title":"Forms and Server Actions","minutes":25,"body":"Server Actions are server-side functions for mutations. Mark them with 'use server' and validate user input and authorization before modifying data.","code":"// app/actions.ts\n'use server';\nexport async function saveName(formData: FormData) {\n  const name = String(formData.get('name') ?? '');\n  if (!name.trim()) throw new Error('Name required');\n  // Validate permissions and persist on server\n}","question":"Which directive marks a Server Action?","choices":["'use server'","'use client'","'use data'"],"correct":0},
{"id":"next-011","month":5,"title":"Metadata and SEO","minutes":25,"body":"Export a metadata object from a server page or layout to control page title and description. Client Components cannot export metadata.","code":"import type { Metadata } from 'next';\nexport const metadata: Metadata = {\n  title: 'Academy',\n  description: 'Learn web development'\n};","question":"Which property sets the page title?","choices":["title","children","href"],"correct":0},
{"id":"next-012","month":5,"title":"Images and Optimization","minutes":25,"body":"next/image helps optimize image delivery and prevent layout shifts when dimensions are known. Remote images require appropriate configuration.","code":"import Image from 'next/image';\nexport default function Logo() {\n  return <Image src='/logo.png' alt='Logo' width={120} height={120} />;\n}","question":"Which prop provides alternative text?","choices":["alt","size","name"],"correct":0},
{"id":"next-013","month":5,"title":"Environment Variables","minutes":25,"body":"Server-only environment variables are not automatically exposed to browsers. NEXT_PUBLIC_ prefixed variables are included in client-side bundles and must not contain secrets.","code":"const apiBase = process.env.NEXT_PUBLIC_API_BASE_URL;\n// Never put private API keys in NEXT_PUBLIC_ variables","question":"Which prefix exposes a variable to client code?","choices":["NEXT_PUBLIC_","PRIVATE_","SECRET_"],"correct":0},
{"id":"next-014","month":5,"title":"Caching and Revalidation","minutes":25,"body":"Next.js provides caching and revalidation controls. Explicitly select caching behavior for data that must stay fresh.","code":"const response = await fetch('https://example.com/api/news', {\n  cache: 'no-store'\n});","question":"What does cache: 'no-store' request?","choices":["Fresh fetch without storing in Next.js data cache","Permanent caching","LocalStorage access"],"correct":0},
{"id":"next-015","month":5,"title":"Deployment and Production Checks","minutes":25,"body":"Before deployment, run lint, type checks and a production build. Keep secrets on the server and verify environment settings.","code":"// Terminal commands\n// npm run build\n// npm run start\n// Confirm deployment environment variables","question":"Which command creates a Next.js production build?","choices":["npm run build","npm run dev","npm install"],"correct":0},
{"id":"next-016","month":5,"title":"Mini Project: Blog Route","minutes":25,"body":"Create a simple dynamic blog route with typed async params and a server-rendered page. Extend it later with real content and a database.","code":"// app/blog/[slug]/page.tsx\nexport default async function BlogPost({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  return <article><h1>Post: {slug}</h1></article>;\n}","question":"Which value is read from the dynamic URL?","choices":["slug","children","metadata"],"correct":0},
{"id":"backend-001","month":6,"title":"Node.js Runtime","minutes":25,"body":"Node.js runs JavaScript outside the browser using the V8 engine. It is commonly used to build servers, command-line tools and APIs.","code":"// server.js\nconsole.log('Node.js running');\n// Run with: node server.js","question":"What command executes server.js?","choices":["node server.js","npm create server","git server.js"],"correct":0},
{"id":"backend-002","month":6,"title":"npm and package.json","minutes":25,"body":"npm installs packages and runs scripts. package.json records dependencies, metadata and useful project commands.","code":"// package.json example\n// { \"scripts\": { \"dev\": \"node server.js\" } }\n// Run: npm run dev","question":"Where are npm scripts defined?","choices":["package.json","README.md","index.html"],"correct":0},
{"id":"backend-003","month":6,"title":"CommonJS and ES Modules","minutes":25,"body":"Node.js supports CommonJS and ES modules. In an ES module, use import/export; CommonJS uses require/module.exports.","code":"// math.mjs\nexport const add = (a, b) => a + b;\n// app.mjs\nimport { add } from './math.mjs';","question":"Which syntax imports a named ES module export?","choices":["import { add }","require.default","module.import"],"correct":0},
{"id":"backend-004","month":6,"title":"HTTP Methods and Status Codes","minutes":25,"body":"HTTP APIs use methods such as GET, POST, PATCH and DELETE. Status 200 indicates success; 201 creation; 404 missing resource.","code":"// Example API contract\n// GET /tasks -> 200 OK\n// POST /tasks -> 201 Created\n// GET /tasks/unknown -> 404 Not Found","question":"Which status usually means a resource was created?","choices":["201","404","500"],"correct":0},
{"id":"backend-005","month":6,"title":"Express Server Basics","minutes":25,"body":"Express is a Node.js web framework. Create an app, register routes, and start listening on a port.","code":"import express from 'express';\nconst app = express();\napp.get('/health', (_req, res) => res.json({ ok: true }));\napp.listen(3000);","question":"Which method registers a GET route?","choices":["app.get","app.listen","app.useJson"],"correct":0},
{"id":"backend-006","month":6,"title":"Routing and URL Parameters","minutes":25,"body":"Express route parameters identify resources in a URL. Read them from req.params and validate before querying data.","code":"app.get('/users/:id', (req, res) => {\n  res.json({ id: req.params.id });\n});","question":"Where is the :id route parameter available?","choices":["req.params.id","req.body.id","res.params.id"],"correct":0},
{"id":"backend-007","month":6,"title":"JSON Request Bodies","minutes":25,"body":"express.json() parses incoming JSON requests and sets req.body. Always validate incoming data before storing it.","code":"app.use(express.json());\napp.post('/notes', (req, res) => {\n  const title = req.body?.title;\n  if (typeof title !== 'string') return res.status(400).json({ error: 'Invalid title' });\n  return res.status(201).json({ title });\n});","question":"Which middleware parses JSON bodies?","choices":["express.json()","express.static()","app.listen()"],"correct":0},
{"id":"backend-008","month":6,"title":"Middleware Pipeline","minutes":25,"body":"Express middleware runs in registration order. Call next() to continue, or send a response to finish the request.","code":"app.use((req, _res, next) => {\n  console.log(req.method, req.path);\n  next();\n});","question":"Which function passes control to the next middleware?","choices":["next()","listen()","render()"],"correct":0},
{"id":"backend-009","month":6,"title":"REST API Design","minutes":25,"body":"REST-style APIs model resources using predictable URLs and HTTP methods. Keep naming consistent and return meaningful status codes.","code":"// GET /tasks: list\n// POST /tasks: create\n// PATCH /tasks/:id: update\n// DELETE /tasks/:id: remove","question":"Which method usually updates part of a resource?","choices":["PATCH","GET","OPTIONS"],"correct":0},
{"id":"backend-010","month":6,"title":"Input Validation","minutes":25,"body":"Never trust user input. Validate types, lengths and allowed values at the API boundary before using data.","code":"function validTitle(value) {\n  return typeof value === 'string' && value.trim().length > 0 && value.length <= 100;\n}\nconsole.log(validTitle('Learn Node'));","question":"Which input should be rejected?","choices":["'Learn Node'","''","'API'"],"correct":1},
{"id":"backend-011","month":6,"title":"Error Handling in Express","minutes":25,"body":"Use centralized error-handling middleware for consistent responses. Avoid exposing internal stack traces to clients.","code":"app.use((err, _req, res, _next) => {\n  console.error(err);\n  res.status(500).json({ error: 'Internal server error' });\n});","question":"How many arguments identify Express error middleware?","choices":["2","3","4"],"correct":2},
{"id":"backend-012","month":6,"title":"Authentication vs Authorization","minutes":25,"body":"Authentication verifies identity; authorization decides what an authenticated user may access. Both are needed for protected resources.","code":"// Example access rule\nfunction canEdit(user, task) {\n  return user.id === task.ownerId;\n}","question":"What does authorization determine?","choices":["User identity","Allowed actions","Server port"],"correct":1},
{"id":"backend-013","month":6,"title":"Password Hashing","minutes":25,"body":"Never store plaintext passwords. Use a reputable password-hashing algorithm such as Argon2id or bcrypt with suitable settings.","code":"// Conceptual example (requires argon2 package)\nconst hash = await argon2.hash(password);\nconst valid = await argon2.verify(hash, candidate);","question":"Which value should be stored?","choices":["Plaintext password","Password hash","Password reminder"],"correct":1},
{"id":"backend-014","month":6,"title":"JWT Fundamentals","minutes":25,"body":"A JWT is a signed token containing claims. Verify signature, issuer, audience and expiration; never treat decoded claims as trusted without verification.","code":"// Conceptual flow\n// 1. Verify JWT signature and claims\n// 2. Read authenticated user ID\n// 3. Check authorization for requested resource","question":"Is simply decoding a JWT enough to trust it?","choices":["Yes","No","Only on mobile"],"correct":1},
{"id":"backend-015","month":6,"title":"Environment Variables and Secrets","minutes":25,"body":"Use environment variables for configuration and secrets. Do not commit API keys or database passwords to source control.","code":"const port = Number(process.env.PORT ?? 3000);\n// Keep DB_PASSWORD on the server, never in a public bundle","question":"Where should private API keys be kept?","choices":["Public client bundle","Server-side secret storage","README"],"correct":1},
{"id":"backend-016","month":6,"title":"CORS and Rate Limiting","minutes":25,"body":"CORS controls which browser origins can read responses. Rate limiting helps reduce abuse but does not replace authentication.","code":"// Conceptual middleware setup\n// app.use(cors({ origin: 'https://example.com' }));\n// app.use(rateLimit({ windowMs: 60000, limit: 60 }));","question":"Does CORS replace authentication?","choices":["Yes","No","For GET only"],"correct":1},
{"id":"backend-017","month":6,"title":"Database Integration Basics","minutes":25,"body":"A backend can persist data in a database. Validate data and handle connection failures. Never embed production credentials in code.","code":"// Pseudocode\n// const task = await db.tasks.findById(id);\n// if (!task) return res.status(404).json({ error: 'Not found' });","question":"What should an API return when a requested record is missing?","choices":["404","201","204"],"correct":0},
{"id":"backend-018","month":6,"title":"Async Route Handlers","minutes":25,"body":"Database and network operations are asynchronous. Use async/await and handle rejected promises in a way compatible with your Express version.","code":"app.get('/status', async (_req, res) => {\n  const status = await Promise.resolve({ ready: true });\n  res.json(status);\n});","question":"Which keyword waits for a Promise inside an async function?","choices":["await","yield","throw"],"correct":0},
{"id":"backend-019","month":6,"title":"API Testing","minutes":25,"body":"Test status codes, response bodies, validation errors and authorization. Automated integration tests catch regressions before deployment.","code":"// Example assertions (pseudocode)\n// expect(response.status).toBe(201);\n// expect(response.body.title).toBe('Read');","question":"Which status would a successful create test commonly expect?","choices":["201","401","503"],"correct":0},
{"id":"backend-020","month":6,"title":"Mini Project: Task REST API","minutes":25,"body":"Combine Express, JSON middleware, validation and routes into a simple in-memory task API. Data is reset when the server restarts.","code":"import express from 'express';\nconst app = express();\napp.use(express.json());\nconst tasks = [];\napp.get('/tasks', (_req, res) => res.json(tasks));\napp.post('/tasks', (req, res) => {\n  const title = req.body?.title;\n  if (typeof title !== 'string' || !title.trim()) return res.status(400).json({ error: 'Title required' });\n  const task = { id: tasks.length + 1, title };\n  tasks.push(task);\n  return res.status(201).json(task);\n});\napp.listen(3000);","question":"Where are the mini-project tasks stored?","choices":["In memory","In MongoDB","In SQLite"],"correct":0},
{"id":"db-001","month":7,"title":"Relational vs Document Databases","minutes":25,"body":"Relational databases store rows in tables; document databases such as MongoDB store flexible BSON documents in collections. Choose based on query and consistency needs.","code":"// Example MongoDB document\nconst user = { name: 'Ada', skills: ['JS', 'Node'] };","question":"Which database model stores BSON documents?","choices":["Document database","Relational table","CSV file"],"correct":0},
{"id":"db-002","month":7,"title":"MongoDB Documents and Collections","minutes":25,"body":"MongoDB groups documents into collections. Each document has a unique _id field, commonly an ObjectId.","code":"// MongoDB shell\n// db.users.insertOne({ name: 'Ada' });\n// db.users.findOne({ name: 'Ada' });","question":"Which field uniquely identifies a document?","choices":["_id","name","createdAt"],"correct":0},
{"id":"db-003","month":7,"title":"Connecting with MongoDB Driver","minutes":25,"body":"The official MongoDB Node.js driver uses MongoClient. Keep connection strings in environment variables and reuse connections.","code":"import { MongoClient } from 'mongodb';\nconst client = new MongoClient(process.env.MONGODB_URI);\nawait client.connect();\nconst db = client.db('academy');","question":"Which class manages MongoDB connections?","choices":["MongoClient","MongoRouter","MongoServer"],"correct":0},
{"id":"db-004","month":7,"title":"Create: insertOne and insertMany","minutes":25,"body":"insertOne adds a document and returns an insertedId. insertMany adds multiple documents in a single operation.","code":"const result = await db.collection('tasks').insertOne({ title: 'Study', done: false });\nconsole.log(result.insertedId);","question":"Which operation inserts one document?","choices":["insertOne","findOne","updateOne"],"correct":0},
{"id":"db-005","month":7,"title":"Read: find and findOne","minutes":25,"body":"findOne returns a matching document or null. find returns a cursor for iterating multiple matching documents.","code":"const task = await db.collection('tasks').findOne({ done: false });\nconst tasks = await db.collection('tasks').find({ done: false }).toArray();","question":"Which method returns a cursor?","choices":["find","findOne","insertOne"],"correct":0},
{"id":"db-006","month":7,"title":"Update Operators","minutes":25,"body":"Use $set to change specific fields and $inc to increment numbers. updateOne modifies the first matching document.","code":"await db.collection('stats').updateOne(\n  { userId: 'ada' },\n  { $inc: { points: 1 } }\n);","question":"Which operator increments a numeric field?","choices":["$set","$inc","$pushAll"],"correct":1},
{"id":"db-007","month":7,"title":"Delete Operations","minutes":25,"body":"deleteOne removes one matching document; deleteMany removes all matches. Filter carefully to avoid deleting unintended data.","code":"const result = await db.collection('tasks').deleteOne({ title: 'Old task' });\nconsole.log(result.deletedCount);","question":"Which method removes one matching document?","choices":["deleteOne","findOne","dropDatabase"],"correct":0},
{"id":"db-008","month":7,"title":"Query Operators","minutes":25,"body":"MongoDB supports operators such as $gt, $gte, $in and $and for expressive filters. Use explicit query criteria.","code":"const adults = await db.collection('users').find({ age: { $gte: 18 } }).toArray();","question":"What does $gte mean?","choices":["Greater than or equal","Less than","Not equal"],"correct":0},
{"id":"db-009","month":7,"title":"Projection and Sorting","minutes":25,"body":"Projection chooses fields returned from a query. sort orders results; limit bounds the result count.","code":"const users = await db.collection('users')\n  .find({}, { projection: { name: 1, _id: 0 } })\n  .sort({ name: 1 }).limit(10).toArray();","question":"What does sort({ name: 1 }) do?","choices":["Ascending sort","Descending sort","Deletes names"],"correct":0},
{"id":"db-010","month":7,"title":"Indexes and Query Performance","minutes":25,"body":"Indexes help MongoDB find matching documents without scanning every record, but add write and storage overhead.","code":"await db.collection('users').createIndex({ email: 1 }, { unique: true });","question":"What does unique: true enforce?","choices":["No duplicate indexed values","Faster network","Unlimited documents"],"correct":0},
{"id":"db-011","month":7,"title":"Schema Design and Embedding","minutes":25,"body":"Embed related data that is typically read together and remains bounded. Reference large or independently updated entities.","code":"const order = {\n  customerId: 'u1',\n  items: [{ productId: 'p1', quantity: 2 }]\n};","question":"What is embedded in the order document?","choices":["items array","A separate server","A SQL table"],"correct":0},
{"id":"db-012","month":7,"title":"References and Relationships","minutes":25,"body":"MongoDB references store identifiers pointing to other documents. Application code or aggregation can resolve relationships.","code":"const post = { title: 'Intro', authorId: 'user-123' };\n// Resolve authorId against users collection","question":"Which field references the author?","choices":["authorId","title","_id only"],"correct":0},
{"id":"db-013","month":7,"title":"Mongoose Models and Schemas","minutes":25,"body":"Mongoose defines schemas and models for MongoDB documents in Node.js applications. Validation helps but does not replace API input checks.","code":"import mongoose from 'mongoose';\nconst taskSchema = new mongoose.Schema({ title: { type: String, required: true } });\nconst Task = mongoose.model('Task', taskSchema);","question":"Which function creates a Mongoose model?","choices":["mongoose.model","mongoose.find","mongoose.route"],"correct":0},
{"id":"db-014","month":7,"title":"Mongoose CRUD","minutes":25,"body":"Mongoose models offer create, find, findById and findByIdAndUpdate methods. Handle missing documents and validation failures.","code":"const task = await Task.create({ title: 'Read docs' });\nconst found = await Task.findById(task._id);","question":"Which method retrieves a document by its ID?","choices":["findById","insertMany","removeAll"],"correct":0},
{"id":"db-015","month":7,"title":"Aggregation Pipeline","minutes":25,"body":"Aggregation pipelines process documents through stages such as $match, $group and $sort. They are useful for analytics.","code":"const totals = await db.collection('orders').aggregate([\n  { $group: { _id: '$customerId', total: { $sum: '$amount' } } }\n]).toArray();","question":"Which stage groups documents?","choices":["$group","$limit","$unset"],"correct":0},
{"id":"db-016","month":7,"title":"Pagination","minutes":25,"body":"Use limit with a stable sort and either skip for small datasets or cursor-based pagination for larger changing datasets.","code":"const page = await db.collection('tasks').find({})\n  .sort({ _id: 1 }).skip(20).limit(10).toArray();","question":"How many documents can this page return at most?","choices":["10","20","30"],"correct":0},
{"id":"db-017","month":7,"title":"Transactions","minutes":25,"body":"Transactions group multiple writes into an atomic unit. They require an appropriate MongoDB deployment and should be kept short.","code":"const session = client.startSession();\ntry {\n  await session.withTransaction(async () => {\n    await db.collection('accounts').updateOne({ _id: 'a' }, { $inc: { balance: -10 } }, { session });\n    await db.collection('accounts').updateOne({ _id: 'b' }, { $inc: { balance: 10 } }, { session });\n  });\n} finally { await session.endSession(); }","question":"What is the purpose of a transaction?","choices":["Atomic multi-operation changes","Faster UI animation","Replacing indexes"],"correct":0},
{"id":"db-018","month":7,"title":"MongoDB Atlas and Connection Safety","minutes":25,"body":"Atlas is a managed MongoDB service. Use restricted database users, network access rules and secret environment variables.","code":"// .env (never commit)\n// MONGODB_URI=mongodb+srv://<credentials>@<host>/academy\n// Validate connection with a ping during setup","question":"Where should the Atlas connection string be stored?","choices":["Server environment variable","Public frontend code","GitHub README"],"correct":0},
{"id":"db-019","month":7,"title":"Backup and Data Security","minutes":25,"body":"Use least-privilege database accounts, encrypted connections, tested backups and careful logging. Do not log credentials or personal data.","code":"// Security checklist\n// - restrict DB user permissions\n// - rotate credentials\n// - test restoring backups","question":"Which practice reduces impact of credential compromise?","choices":["Least privilege","Public credentials","No backups"],"correct":0},
{"id":"db-020","month":7,"title":"Mini Project: MongoDB Task Repository","minutes":25,"body":"Build a small repository layer that reads and writes task documents. Keep database access on the server and validate IDs and inputs at the API boundary.","code":"function taskRepository(db) {\n  const tasks = db.collection('tasks');\n  return {\n    list: () => tasks.find({}).limit(50).toArray(),\n    create: title => tasks.insertOne({ title, done: false }),\n    markDone: id => tasks.updateOne({ _id: id }, { $set: { done: true } })\n  };\n}","question":"Which method updates done to true?","choices":["markDone","list","create"],"correct":0}
] as const;
